const ajv = new AjvClass({strict: false, validateFormats: false, allErrors: true});

function compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`, {cause: error});
  }
}

function formatValidationErrors(errors: ErrorObject[] | null | undefined): string {
  if (!errors || errors.length === 0) return 'input validation failed';
  return errors
    .map(err => {
      const fieldPath = err.instancePath ? err.instancePath.replace(/^\//, '').replace(/\//g, '.') : '';
      if (err.keyword === 'required' && err.params && typeof err.params.missingProperty === 'string') {
        const missingProp = err.params.missingProperty;
        const fullPath = fieldPath ? `${fieldPath}.${missingProp}` : missingProp;
        return `missing required property "${fullPath}"`;
      }
      const target = fieldPath ? `property "${fieldPath}"` : 'input';
      return `${target} ${err.message ?? 'is invalid'}`;
    })
    .join('; ');
}

